import{_ as d,l as s,o as a,c as i,v as r,p as c,x as o,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"错误恢复","description":"","frontmatter":{"title":"错误恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/parse-error-recovery.md","filePath":"cs/parse-error-recovery.md","lastUpdated":1789023840000}'),h={name:"cs/parse-error-recovery.md"};function E(_,e,u,m,f,A){const t=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="错误恢复" tabindex="-1">错误恢复 <a class="header-anchor" href="#错误恢复" aria-label="Permalink to &quot;错误恢复&quot;">​</a></h1><div class="epigraph"><p>分析器的职责不止于第一个非法记号：要报告、要跳到能再同步的符号，并尽量不引发雪崩式误报。</p><footer>—— 据龙书第 4 章错误恢复；Burke and Fisher, A Practical Method for LR and LL Syntax Error Diagnosis and Recovery 整理</footer></div><p>上一课<a href="/cs/pratt-parsing">Pratt</a>在合法表达式上漂亮。真实编译器面对缺括号、多逗号。主干 LL 课点过 FOLLOW 作同步集。缺口是<strong>恢复策略</strong>：恐慌模式、短语级修补、yacc 的 <code>error</code> 记号。本课钉「报告一次、跳过、继续」，不把 IDE 的红线协议写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>查表空或 nud 缺失：输入不是语言的前缀。若立刻 <code>exit</code>，用户只看见第一处。若胡乱插入记号，后续整棵树错位，报错上百条。缺口是<strong>同步</strong>：丢弃直到遇见 <code>;</code>、<code>}</code> 或 FOLLOW 中的记号，使栈与输入再次对齐。</p><p>yacc：<code>error</code> 产生式允许在某非终结符下吃掉错误短语。bison 的 <code>yyerrok</code> 解除「刚恢复」抑制，避免相邻错误被吞。</p><h3 id="同步不是「猜对用户意思」" tabindex="-1">同步不是「猜对用户意思」 <a class="header-anchor" href="#同步不是「猜对用户意思」" aria-label="Permalink to &quot;同步不是「猜对用户意思」&quot;">​</a></h3><p>恢复后的 AST 可以残缺，类型检查必须能容忍空洞节点。不要在恢复里做复杂程序变换。语义动作里申请的内存要能在弹出栈时释放——上一课 yacc 已点过所有权。</p><p><span class="marginnote">龙书 4.1.4 与 4.5.5。Burke–Fisher 讨论 LR/LL 诊断。本课不把 GLR 多栈恢复写成算法作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>恐慌：从当前记号丢到同步集。短语级：尝试插入/删除一个记号看能否继续（限一步，防组合爆炸）。错误产生式：文法里显式 <code>error</code>。统一：每个语法错误一条主诊断，带行号；恢复后计数，太多则停。</p>',11)),(a(),c(p,null,{default:o(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E9%9D%9E%E6%B3%95%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%22%5D%0A%20%20REP%20--%3E%20SYNC%5B%22%E4%B8%A2%E5%BC%83%E8%87%B3%E5%90%8C%E6%AD%A5%E9%9B%86%22%5D%0A%20%20SYNC%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E5%88%86%E6%9E%90%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>词法错误（非法字符）在 lex 动作里吞掉一字并警告，不要把垃圾字符送进语法栈。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>雪崩：缺一个 <code>)</code> 会导致整份参数列表全部「期望逗号」。抑制：同一行或同一子树只报一次。LR 比 LL 更难点「期望什么」：状态里有多条项。实用做法：列出该状态可移进的记号集合，截断显示。</p><p>PEG 的有序选择把失败藏在左枝，诊断要另记最深失败位置（Ford 也讨论过误差报告），与 LR 的 FOLLOW 不同源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 tree-sitter 的增量，不算最小编辑距离的全局最优修补。后课默认：前端能在错误后同步并继续建残树。下一课：编辑器里改一个字符不必重头分析——增量解析。</p><p>不要承诺「总能恢复成用户意图」。恢复的契约是：编译器进程不崩，诊断位置可信。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恢复 = 报告 + 同步 + 抑制雪崩。</li><li><code>error</code> 记号与 FOLLOW 同步是两条实用路。</li><li>残树必须让后遍可拒绝而非误优化。</li><li>出处：Aho et al., 龙书；Burke and Fisher。</li></ul>',9))])}const P=d(h,[["render",E]]);export{B as __pageData,P as default};
